function portal_google_base64url(string $bytes): string { return rtrim(strtr(base64_encode($bytes), '+/', '-_'), '='); }
function portal_google_begin_authorization(array $config): string { if(!portal_google_login_configured($config))throw new RuntimeException('Google 登入尚未完成設定。');$verifier=portal_google_base64url(random_bytes(64));$state=portal_google_base64url(random_bytes(32));$nonce=portal_google_base64url(random_bytes(32));$_SESSION['google_oauth']=['state'=>$state,'nonce'=>$nonce,'verifier'=>$verifier,'created_at'=>time()];return 'https://accounts.google.com/o/oauth2/v2/auth?'.http_build_query(['client_id'=>(string)$config['google_oauth_client_id'],'redirect_uri'=>(string)$config['google_oauth_redirect_uri'],'response_type'=>'code','scope'=>'openid email profile','state'=>$state,'nonce'=>$nonce,'code_challenge'=>portal_google_base64url(hash('sha256',$verifier,true)),'code_challenge_method'=>'S256','prompt'=>'select_account'],'','&',PHP_QUERY_RFC3986); }
function portal_google_http_json(string $url,string $ca,array $fields=[]): array { if(!function_exists('curl_init')||!is_file($ca)||!is_readable($ca))throw new RuntimeException('Google 驗證服務目前無法使用。');$h=curl_init($url);curl_setopt_array($h,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>20,CURLOPT_CAINFO=>realpath($ca),CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_HTTPHEADER=>['Accept: application/json']]);if($fields!==[]){curl_setopt($h,CURLOPT_POST,true);curl_setopt($h,CURLOPT_POSTFIELDS,http_build_query($fields,'','&',PHP_QUERY_RFC3986));} $body=curl_exec($h);$status=(int)curl_getinfo($h,CURLINFO_RESPONSE_CODE);curl_close($h);if(!is_string($body)||$status!==200||strlen($body)>65536)throw new RuntimeException('Google 驗證服務目前無法使用。');$json=json_decode($body,true,32,JSON_THROW_ON_ERROR);if(!is_array($json))throw new RuntimeException('Google 驗證回應格式不正確。');return $json; }
function portal_google_exchange_code(array $config,string $code,string $verifier,string $nonce): array { if($code===''||strlen($code)>4096||$verifier==='')throw new RuntimeException('Google 登入回應不完整。');$tokens=portal_google_http_json('https://oauth2.googleapis.com/token',(string)$config['google_ca_bundle'],['code'=>$code,'client_id'=>(string)$config['google_oauth_client_id'],'client_secret'=>(string)$config['google_oauth_client_secret'],'redirect_uri'=>(string)$config['google_oauth_redirect_uri'],'grant_type'=>'authorization_code','code_verifier'=>$verifier]);$token=(string)($tokens['id_token']??'');if($token===''||strlen($token)>16384)throw new RuntimeException('Google 登入回應缺少身分憑證。');$claims=portal_google_http_json('https://oauth2.googleapis.com/tokeninfo?id_token='.rawurlencode($token),(string)$config['google_ca_bundle']);$email=portal_account_normalize_google_email((string)($claims['email']??''));$subject=(string)($claims['sub']??'');if($email===null||!hash_equals((string)$config['google_oauth_client_id'],(string)($claims['aud']??''))||!in_array((string)($claims['iss']??''),['accounts.google.com','https://accounts.google.com'],true)||(int)($claims['exp']??0)<time()||!in_array($claims['email_verified']??false,[true,1,'1','true'],true)||$subject===''||strlen($subject)>255||!hash_equals($nonce,(string)($claims['nonce']??'')))throw new RuntimeException('Google 帳號驗證失敗。');return ['email'=>$email,'subject'=>$subject]; }
